package com.rezoxnemesis.videostudio;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Content coverage is evidence of saved drawing data, never anatomical or creative acceptance. */
final class SketchInspection {
 static JSONObject inspect(JSONObject doc,JSONObject args)throws Exception {
  int frames=doc.getInt("frameCount"),offset=args.has("frameOffset")?(int)SketchDocument.integer(args,"frameOffset",0,frames-1):0,limit=args.has("frameLimit")?(int)SketchDocument.integer(args,"frameLimit",1,64):32;
  Set<String> characters=new LinkedHashSet<>();JSONArray chosen=args.optJSONArray("characterLayerIds");if(chosen!=null){if(chosen.length()>8)throw SketchDocument.bad("Inspect at most eight authored character layers");for(int n=0;n<chosen.length();n++){String id=chosen.getString(n);SketchDocument.layer(doc,id);if(!characters.add(id))throw SketchDocument.bad("Character layers must be unique");}}
  Map<String,String> geometry=new HashMap<>();JSONArray layers=doc.getJSONArray("layers");int objects=0,points=0,keys=0,images=0;
  for(int n=0;n<layers.length();n++){JSONObject layer=layers.getJSONObject(n);keys+=layer.getJSONArray("keys").length();JSONArray items=layer.getJSONArray("objects");for(int k=0;k<items.length();k++){JSONObject object=items.getJSONObject(k);objects++;keys+=object.getJSONArray("keys").length();int[] shapeBudget=SketchShapeKeys.validate(object,frames);keys+=shapeBudget[0];points+=shapeBudget[1];if(object.has("points"))points+=object.getJSONArray("points").length();if(object.has("commands"))points+=SketchDocument.validateCommands(object.getJSONArray("commands"));if("image".equals(object.getString("kind")))images++;JSONObject data=SketchDocument.copy(object);for(String field:new String[]{"id","frame","exposure","keys","transform"})data.remove(field);geometry.put(object.getString("id"),hash(SketchDocument.canonical(data)));}}
  JSONArray rows=new JSONArray();String previous=null;Map<String,String> previousActors=new HashMap<>();
  for(int frame=Math.max(0,offset-1);frame<Math.min(frames,offset+limit);frame++){
   JSONArray content=new JSONArray();JSONObject actorDigests=new JSONObject();int exposed=0,authored=0;
   for(int n=0;n<layers.length();n++){JSONObject layer=layers.getJSONObject(n);if(!layer.getBoolean("visible")||layer.getDouble("opacity")<=0)continue;JSONObject transform=SketchDocument.transformAt(layer,frame);if(transform.getDouble("opacity")<=0)continue;JSONArray paint=new JSONArray(),items=layer.getJSONArray("objects");int layerExposed=0;
    for(int k=0;k<items.length();k++){JSONObject object=items.getJSONObject(k);if(!SketchFrameRenderer.exposed(object,frame))continue;JSONObject pose=SketchDocument.transformAt(object,frame);if(pose.getDouble("opacity")<=0)continue;JSONObject mark=new JSONObject().put("geometry",geometry.get(object.getString("id"))).put("transform",pose);if(SketchShapeKeys.animated(object))mark.put("shapeSha256",hash(SketchShapeKeys.commandsAt(object,frame).toString()));paint.put(mark);exposed++;layerExposed++;if(object.getInt("frame")==frame)authored++;}
    JSONObject layerPaint=new JSONObject().put("transform",transform).put("opacity",layer.getDouble("opacity")).put("blend",layer.optString("blendMode","normal")).put("objects",paint);content.put(layerPaint);if(characters.contains(layer.getString("id")))actorDigests.put(layer.getString("id"),new JSONObject().put("exposedObjects",layerExposed).put("contentSha256",hash(SketchDocument.canonical(layerPaint))));
   }
   String digest=hash(SketchDocument.canonical(content));JSONObject actors=new JSONObject();for(String id:characters){JSONObject actor=actorDigests.optJSONObject(id);if(actor==null)actor=new JSONObject().put("exposedObjects",0).put("contentSha256",hash("hidden-or-empty"));String actorHash=actor.getString("contentSha256");actor.put("contentChanged",previousActors.containsKey(id)&&!previousActors.get(id).equals(actorHash));previousActors.put(id,actorHash);actors.put(id,actor);}
   if(frame>=offset)rows.put(new JSONObject().put("frame",frame).put("exposedObjects",exposed).put("newObjectsStarting",authored).put("contentSha256",digest).put("contentChanged",previous!=null&&!previous.equals(digest)).put("characters",actors));previous=digest;
  }
  JSONArray contourSources=null;
  if(args.has("contourObjectIds")){if(!args.has("expectedRevision"))throw SketchDocument.bad("Contour source inspection requires an exact revision");JSONArray ids=args.getJSONArray("contourObjectIds");if(ids.length()<1||ids.length()>16)throw SketchDocument.bad("Inspect 1..16 distinct authored contour sources");Set<String> distinct=new HashSet<>();contourSources=new JSONArray();for(int i=0;i<ids.length();i++){Object raw=ids.get(i);if(!(raw instanceof String)||!distinct.add((String)raw))throw SketchDocument.bad("Contour IDs must be distinct strings");JSONObject pin=SketchContourPaint.pin(doc,(String)raw);SketchContourPaint.path(pin);contourSources.put(new JSONObject().put("contourObjectId",raw).put("layerId",pin.getString("layerId")).put("contourSha256",pin.getString("sha256")).put("minimumNativeVersion","4.9.4"));}}
  int bytes=doc.toString().getBytes(StandardCharsets.UTF_8).length;JSONObject result=new JSONObject().put("sketchId",doc.getString("id")).put("revision",doc.getLong("revision")).put("documentSha256",hash(SketchDocument.canonical(doc))).put("frameCount",frames).put("fps",doc.getInt("fps")).put("durationUs",NativeFrameClock.presentationTimeUs(frames,doc.getInt("fps"))).put("frameOffset",offset).put("frames",rows).put("moreFrames",offset+rows.length()<frames).put("usage",new JSONObject().put("objects",objects).put("points",points).put("keys",keys).put("images",images).put("bytes",bytes)).put("remainingBudget",new JSONObject().put("objects",SketchDocument.MAX_OBJECTS-objects).put("points",SketchDocument.MAX_POINTS-points).put("keys",SketchDocument.MAX_KEYS-keys).put("images",SketchDocument.MAX_IMAGES-images).put("bytes",SketchDocument.MAX_BYTES-bytes)).put("characterLayerEvidence",characters.isEmpty()?"UNAVAILABLE":"EXPLICIT_LAYER_CONTENT_ONLY").put("creativeQualityVerified",false).put("articulatedMotionVerified",false).put("coverageMeaning","Exposed saved objects and changed content do not establish anatomy, pixel coverage, original likeness or physical motion");if(contourSources!=null)result.put("contourPaintSources",contourSources);return result;
 }
 private static String hash(String value)throws Exception{return SketchDocument.sha256(value.getBytes(StandardCharsets.UTF_8));}
}
